    data = json.load(f)

# Search through the document
def search_exchange_rates(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, str) and any(term in v.lower() for term in ['exchange', 'pound', 'sterling', 'gbp', 'britain']):
                print(f'Found at {path}.{k}: {v[:200]}')
            search_exchange_rates(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search_exchange_rates(item, f'{path}[{i}]')

# Just print the structure first
doc = data.get('document', {})
if isinstance(doc, dict):
    elements = doc.get('elements', [])
    print(f'Number of elements: {len(elements)}')
